const langs = ($input.first().json.languages) || [];
const EXCLUDE_ISO = ['en', 'pst', 'ps', 'cus', 'pt_old'];
const targets = langs.filter(l => !EXCLUDE_ISO.includes(l.lang_iso));
if (targets.length === 0) throw new Error('No target languages resolved');
return [{ json: { targetLangIds: targets.map(l => l.lang_id).join(','), targetCount: targets.length } }];

const scope = $('Build Scope').first().json;
const untrTotal = parseInt(($('Count Untranslated').first().json.headers || {})['x-pagination-total-count'] || '0', 10);
const allTotal = parseInt(($('Count All Keys').first().json.headers || {})['x-pagination-total-count'] || '0', 10);
if (!untrTotal || !allTotal) throw new Error('Missing pagination totals');
const PROJ = 'https://api.lokalise.com/api2/projects/964775386a3ce03ecca883.03770715';
const BASE = PROJ + '/keys';
const LIMIT = 500;
const out = [];
for (let p = 1; p <= Math.ceil(untrTotal / LIMIT); p++) {
  out.push({ json: { url: BASE + '?limit=' + LIMIT + '&page=' + p + '&filter_untranslated=1&filter_translation_lang_ids=' + scope.targetLangIds } });
}
for (let p = 1; p <= Math.ceil(allTotal / LIMIT); p++) {
  out.push({ json: { url: BASE + '?limit=' + LIMIT + '&page=' + p + '&include_translations=1&filter_translation_lang_ids=640' } });
}
// screenshot inventory: separate endpoint, different response shape
for (let p = 1; p <= 8; p++) {
  out.push({ json: { url: PROJ + '/screenshots?limit=500&page=' + p } });
}
return out;

const untranslatedIds = new Set();
const meta = new Map();
for (const it of $input.all()) {
  const b = it.json || {};
  if (Array.isArray(b.screenshots)) continue;
  const keys = b.keys || [];
  if (!Array.isArray(keys) || keys.length === 0) continue;
  const isPassB = Array.isArray(keys[0].translations);
  for (const k of keys) {
    if (isPassB) meta.set(k.key_id, { key_name: (k.key_name && (k.key_name.web || k.key_name.other)) || '', description: k.description || '' });
    else untranslatedIds.add(k.key_id);
  }
}

function sentences(d) {
  return String(d).split(/(?<=\.)\s+/).map(s => s.trim()).filter(Boolean);
}

const variants = {};
let scopeHits = 0, projectHits = 0;
const RE = /figma|no screen in the current|screenshot/i;

for (const [id, m] of meta) {
  const hit = sentences(m.description).filter(s => RE.test(s));
  if (!hit.length) continue;
  projectHits++;
  if (untranslatedIds.has(id)) scopeHits++;
  for (const s of hit) {
    // collapse the variable screen names so variants group
    const norm = s.replace(/Screenshot:.*/i, 'Screenshot: <screen names>');
    variants[norm] = (variants[norm] || 0) + 1;
  }
}

const rows = Object.keys(variants).sort((a, b) => variants[b] - variants[a]).map(v => ({ phrase: v, count: variants[v] }));

return [{ json: {
  scopeSize: untranslatedIds.size,
  projectKeys: meta.size,
  scopeKeysWithFigmaOrScreenshotWording: scopeHits,
  projectKeysWithFigmaOrScreenshotWording: projectHits,
  distinctPhrases: rows.length,
  phrases: rows.slice(0, 25)
} }];
